<script>const series=@json($series),c=document.getElementById('performanceChart'),x=c.getContext('2d');function draw(){const d=devicePixelRatio||1,w=c.clientWidth||900,h=220;c.width=w*d;c.height=h*d;x.scale(d,d);const m=Math.max(...series.map(v=>v.sales),1),l=45,r=12,t=12,b=30;x.strokeStyle='#e2e8f0';for(let i=0;i<4;i++){let y=t+(h-t-b)*i/3;x.beginPath();x.moveTo(l,y);x.lineTo(w-r,y);x.stroke()}if(!series.length)return;x.strokeStyle='#7c3aed';x.lineWidth=3;x.beginPath();series.forEach((p,i)=>{let px=l+(w-l-r)*i/Math.max(series.length-1,1),py=t+(h-t-b)*(1-p.sales/m);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}draw();addEventListener('resize',draw);const feed=document.getElementById('salesFeed'),status=document.getElementById('liveStatus');function safe(s){return String(s??'').replace(/[&<>'"]/g,z=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[z]))}function connect(){const s=new EventSource('{{ route('admin.realtime.sales') }}');s.addEventListener('sales',e=>{const rows=JSON.parse(e.data);if(!rows.length)return;feed.innerHTML=rows.map(o=>`<a href="/admin/orders/${o.id}" class="flex justify-between gap-4 p-4"><div><b>${safe(o.customer)}</b><div class="text-xs text-slate-400">${safe(o.order_number)} · ${safe(o.program||'—')} · ${safe(o.partner||'Direct')}</div></div><div class="text-right"><b>${safe(o.currency||'NGN')} ${Number(o.total).toLocaleString(undefined,{minimumFractionDigits:2})}</b><div class="text-xs text-slate-400">${new Date(o.created_at).toLocaleString()}</div></div></a>`).join('');status.textContent='Live'});s.onerror=()=>{status.textContent='Reconnecting…';s.close();setTimeout(connect,10000)}}connect();</script>
